=UpdateContext({
    varCurrentRecord: Blank(),
    varIsNewMode: true,
    varShowSearch: false, // Hide search bar
    varShowForm: true     // Reveal the form
});

// 2. Trigger mass-reset toggle to clear all text inputs
UpdateContext({ varResetControls: true });
UpdateContext({ varResetControls: false });

=// Reveal the Search container, hide the form until a record is found
UpdateContext({
    varIsNewMode: false,
    varShowSearch: true,
    varShowForm: false
});

// Clear out old search queries
Reset(cmbSearchQuote);
Reset(cmbSearchRFQ);
Reset(cmbSearchPO);

