  Refresh(SalesTracker);
// 1. Ensure at least one box is filled
If(
    IsBlank(cmbSearchQuote.Selected) && IsBlank(cmbSearchRFQ.Selected) && IsBlank(cmbSearchPO.Selected),
    Notify("Please select a Quote, RFQ, or PO Number to search.", NotificationType.Warning),

    // 2. Look up the record based on whichever box they used
    If(
        !IsBlank(cmbSearchQuote.Selected), 
        UpdateContext({varCurrentRecord: LookUp(SalesTracker, Quote_No = cmbSearchQuote.Selected.Quote_No)}),

        !IsBlank(cmbSearchRFQ.Selected), 
        UpdateContext({varCurrentRecord: LookUp(SalesTracker, Project_Name = cmbSearchRFQ.Selected.Project_Name)}),

        !IsBlank(cmbSearchPO.Selected), 
        UpdateContext({varCurrentRecord: LookUp(SalesTracker, PO_Reference= cmbSearchPO.Selected.PO_Reference)})
    );

    // 3. If a record was found, reveal the form!
    If(
        !IsBlank(varCurrentRecord),
        UpdateContext({varShowForm: true}), // Form appears!
        Notify("No matching record found.", NotificationType.Error)
    )
)

=// 1. Return all visibility states to the initial Landing Page setup
UpdateContext({
    varCurrentRecord: Blank(),
    varIsNewMode: false,
    varShowForm: false,     // Hides the main form
    varShowSearch: false    // Hides the 3 search boxes
});

// 2. Safely wipe out and clear all search dropdowns
Reset(cmbSearchQuote);
Reset(cmbSearchRFQ);
Reset(cmbSearchPO);
Refresh(SalesTracker);
// 3. Now trigger the mass-reset toggle to clear all text inputs & dropdowns inside Container1
UpdateContext({ varResetControls: true });
UpdateContext({ varResetControls: false });
